// JSON与二进制只负责无损承载和形状拒绝；真实服务/付款/伤因与死亡仍由完整来源核验。
#include "resident/checkpoint/checkpoint_decode_lifecycle.hpp"
#include "growth_recovery_codec.hpp"
#include "resident/storage/common_checkpoint.hpp"
#include <set>
namespace hanmo::resident {namespace {
using V=BoundaryValue;
// 直接C++ BoundaryValue也必须拒重复键，不能只依赖文本解析器的first-match行为。
void unique(const V& value,Integer depth=0){if(depth>64)boundary::fail("GrowthRecoveryBoundaryTooDeep","");if(const auto* object=value.as<V::Dict>()){std::set<StableId> keys;for(const auto& row:*object){if(!keys.insert(row.first).second)boundary::fail("DuplicateGrowthRecoveryField",row.first);unique(row.second,depth+1);}}else if(const auto* array=value.as<V::Array>())for(const auto& row:*array)unique(row,depth+1);}
GrowthRecoveryService read_service(const V& value){using namespace boundary;fields(value,{"actor_id","provider_actor_id","role_id","place_id","method","start_tick","duration"},{},"service");GrowthRecoveryService out;out.actor_id=get_string(value,"actor_id","service");out.provider_actor_id=get_string(value,"provider_actor_id","service");out.role_id=get_string(value,"role_id","service");out.place_id=get_string(value,"place_id","service");const auto method=get_int(value,"method","service");if(method<0||method>1)fail("InvalidGrowthRecoveryMethod","service");out.method=static_cast<GrowthRecoveryMethod>(method);out.start_tick=get_int(value,"start_tick","service");out.duration=get_int(value,"duration","service");out.field_order=order(value);return out;}
Status emit(ProjectionWriter& out,const GrowthRecoveryService& p){out.field("actor_id",p.actor_id);out.field("provider_actor_id",p.provider_actor_id);out.field("role_id",p.role_id);out.field("place_id",p.place_id);out.field("method",static_cast<Integer>(p.method));out.field("start_tick",p.start_tick);out.field("duration",p.duration);return out.order_fields(p.field_order);}
Status visit(CodecVisitor& c,GrowthRecoveryService& p){c.field("actor_id",p.actor_id);c.field("provider_actor_id",p.provider_actor_id);c.field("role_id",p.role_id);c.field("place_id",p.place_id);Integer method=static_cast<Integer>(p.method);c.field("method",method);if(method<0||method>1)return c.reject("InvalidGrowthRecoveryMethod");if(c.reading())p.method=static_cast<GrowthRecoveryMethod>(method);c.field("start_tick",p.start_tick);c.field("duration",p.duration);common_checkpoint::strings(c,"field_order",p.field_order);return c.status();}
GrowthRecoveryStep read_step(const V& value){using namespace boundary;fields(value,{"kind","action_id","tick","ordinal","injury_before","points_before","injury_after","points_after","offered_points","used_points"},{},"step");GrowthRecoveryStep out;out.kind=get_string(value,"kind","step");out.action_id=get_string(value,"action_id","step");out.tick=get_int(value,"tick","step");out.ordinal=get_int(value,"ordinal","step");out.before.injury=get_int(value,"injury_before","step");out.before.points=get_int(value,"points_before","step");out.after.injury=get_int(value,"injury_after","step");out.after.points=get_int(value,"points_after","step");out.offered_points=get_int(value,"offered_points","step");out.used_points=get_int(value,"used_points","step");out.field_order=order(value);return out;}
Status emit(ProjectionWriter& out,const GrowthRecoveryStep& p){out.field("kind",p.kind);out.field("action_id",p.action_id);out.field("tick",p.tick);out.field("ordinal",p.ordinal);out.field("injury_before",p.before.injury);out.field("points_before",p.before.points);out.field("injury_after",p.after.injury);out.field("points_after",p.after.points);out.field("offered_points",p.offered_points);out.field("used_points",p.used_points);return out.order_fields(p.field_order);}
Status visit(CodecVisitor& c,GrowthRecoveryStep& p){c.field("kind",p.kind);c.field("action_id",p.action_id);c.field("tick",p.tick);c.field("ordinal",p.ordinal);c.field("injury_before",p.before.injury);c.field("points_before",p.before.points);c.field("injury_after",p.after.injury);c.field("points_after",p.after.points);c.field("offered_points",p.offered_points);c.field("used_points",p.used_points);common_checkpoint::strings(c,"field_order",p.field_order);return c.status();}
GrowthRecoveryClosure read_closure(const V& value){using namespace boundary;fields(value,{"kind","action_id","tick","provided_half_days","reason","cause_fact_id","commit_result_id","commit_actor_id","commit_kind","commit_request_seq","commit_revision","commit_advance"},{},"closure");GrowthRecoveryClosure out;out.kind=get_string(value,"kind","closure");out.action_id=get_string(value,"action_id","closure");out.tick=get_int(value,"tick","closure");out.provided_half_days=get_int(value,"provided_half_days","closure");out.reason=get_string(value,"reason","closure");out.cause_fact_id=get_string(value,"cause_fact_id","closure");out.commit_result_id=get_string(value,"commit_result_id","closure");out.commit_actor_id=get_string(value,"commit_actor_id","closure");out.commit_kind=get_string(value,"commit_kind","closure");out.commit_request_seq=get_int(value,"commit_request_seq","closure");out.commit_revision=get_int(value,"commit_revision","closure");out.commit_advance=get_bool(value,"commit_advance","closure");out.field_order=order(value);return out;}
Status emit(ProjectionWriter& out,const GrowthRecoveryClosure& p){out.field("kind",p.kind);out.field("action_id",p.action_id);out.field("tick",p.tick);out.field("provided_half_days",p.provided_half_days);out.field("reason",p.reason);out.field("cause_fact_id",p.cause_fact_id);out.field("commit_result_id",p.commit_result_id);out.field("commit_actor_id",p.commit_actor_id);out.field("commit_kind",p.commit_kind);out.field("commit_request_seq",p.commit_request_seq);out.field("commit_revision",p.commit_revision);out.field("commit_advance",p.commit_advance);return out.order_fields(p.field_order);}
Status visit(CodecVisitor& c,GrowthRecoveryClosure& p){c.field("kind",p.kind);c.field("action_id",p.action_id);c.field("tick",p.tick);c.field("provided_half_days",p.provided_half_days);c.field("reason",p.reason);c.field("cause_fact_id",p.cause_fact_id);c.field("commit_result_id",p.commit_result_id);c.field("commit_actor_id",p.commit_actor_id);c.field("commit_kind",p.commit_kind);c.field("commit_request_seq",p.commit_request_seq);c.field("commit_revision",p.commit_revision);c.field("commit_advance",p.commit_advance);common_checkpoint::strings(c,"field_order",p.field_order);return c.status();}
}
Outcome<GrowthRecoveryState> decode_growth_recovery_state(const V& v){try{using namespace boundary;unique(v);fields(v,{"version","services","credits","closures"},{},"personal_injury_recovery");if(get_int(v,"version","")!=1)fail("UnsupportedGrowthRecoveryVersion","");GrowthRecoveryState out;
for(const auto& row:object(field(v,"services",""),"services"))if(!out.services.insert(row.first,read_service(row.second)))fail("DuplicateGrowthRecoveryRecord",row.first);
for(const auto& row:object(field(v,"credits",""),"credits"))if(!out.credits.insert(row.first,read_step(row.second)))fail("DuplicateGrowthRecoveryRecord",row.first);
for(const auto& row:object(field(v,"closures",""),"closures"))if(!out.closures.insert(row.first,read_closure(row.second)))fail("DuplicateGrowthRecoveryRecord",row.first);
out.field_order=order(v);auto valid=validate_growth_recovery_shape(out);if(!valid.ok)return {false,{},valid.error};return {true,std::move(out),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Status emit_growth_recovery_state_fields(ProjectionWriter& out,const GrowthRecoveryState& s){
    auto valid=validate_growth_recovery_shape(s);if(!valid.ok)return valid;
    out.field("version",Integer{1});
    out.object("services",[&](auto& w){for(const auto& row:s.services.rows()){auto status=w.object(row.first,[&](auto& fields){return emit(fields,row.second);});if(!status.ok)return status;}return w.status();});
    out.object("credits",[&](auto& w){for(const auto& row:s.credits.rows()){auto status=w.object(row.first,[&](auto& fields){return emit(fields,row.second);});if(!status.ok)return status;}return w.status();});
    out.object("closures",[&](auto& w){for(const auto& row:s.closures.rows()){auto status=w.object(row.first,[&](auto& fields){return emit(fields,row.second);});if(!status.ok)return status;}return w.status();});
    return out.order_fields(s.field_order);
}
Status emit_growth_recovery_state_projection(ProjectionWriter& out,std::string_view name,const GrowthRecoveryState& s){return out.object(name,[&](auto& fields){return emit_growth_recovery_state_fields(fields,s);});}
BoundaryValue encode_growth_recovery_state(const GrowthRecoveryState& s){BoundaryValue value;BoundaryProjectionWriter out(value);auto status=emit_growth_recovery_state_projection(out,"",s);if(status.ok)status=out.finish();if(!status.ok){boundary::DecodeFailure failure(status.error.original.code,status.error.original.path);failure.error=status.error;throw failure;}return value;}
Status visit_growth_recovery_checkpoint(CodecVisitor& c,GrowthRecoveryState& s){Integer version=1;c.field("version",version);if(version!=1)return c.reject("UnsupportedGrowthRecoveryVersion");common_checkpoint::table(c,"services",s.services,[](CodecVisitor& q,GrowthRecoveryService& v){return visit(q,v);});common_checkpoint::table(c,"credits",s.credits,[](CodecVisitor& q,GrowthRecoveryStep& v){return visit(q,v);});common_checkpoint::table(c,"closures",s.closures,[](CodecVisitor& q,GrowthRecoveryClosure& v){return visit(q,v);});common_checkpoint::strings(c,"field_order",s.field_order);if(!c.status().ok)return c.status();auto valid=validate_growth_recovery_shape(s);return valid.ok?c.status():c.reject(valid.error.original.code);}
}
